// Same rows the websocket sends in MEDIA_QUEUE_UPDATE.
function beta_mp_queue($db): array {
    $now = null; $queue = [];
    try {
        $r = $db->query("SELECT id, video_id, title, requested_by, duration_seconds FROM media_queue WHERE status='playing' ORDER BY id LIMIT 1");
        if ($r) $now = $r->fetch_assoc() ?: null;
        $r = $db->query("SELECT id, video_id, title, requested_by, duration_seconds FROM media_queue WHERE status='queued' ORDER BY id");
        while ($r && ($row = $r->fetch_assoc())) $queue[] = $row;
    } catch (Throwable $e) {}
    return ['now_playing' => $now, 'queue' => $queue];
}
// One short socket.io (Engine.IO v4 polling) session: REGISTER as the live
// page's "Media Controller", send the MEDIA_COMMAND, wait for the reply, leave.
function beta_mp_emit(string $key, array $payload): bool {
    $base = 'https://websocket.botofthespecter.com/socket.io/?EIO=4&transport=polling';
    $req = function (string $url, ?string $body = null) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 8, CURLOPT_CONNECTTIMEOUT => 4]);
        if ($body !== null) { curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_POSTFIELDS, $body); curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: text/plain;charset=UTF-8']); }
        $out = curl_exec($ch); $code = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        return ($out === false || $code !== 200) ? null : (string) $out;
    };
    $open = $req($base . '&t=' . bin2hex(random_bytes(4)));
    if ($open === null || ($open[0] ?? '') !== '0') return false;
    $hs = json_decode(substr($open, 1), true);
    $sid = (string) ($hs['sid'] ?? '');
    if ($sid === '') return false;
    $u = $base . '&sid=' . rawurlencode($sid);
    $wait = function (string $event) use ($req, $u) {
        for ($i = 0; $i < 4; $i++) {
            $got = $req($u . '&t=' . bin2hex(random_bytes(4)));
            if ($got === null) return false;
            foreach (explode("\x1e", $got) as $pkt) { if (strpos($pkt, '42["' . $event . '"') === 0 || ($event === '' && strpos($pkt, '40') === 0)) return true; }
        }
        return false;
    };
    $ok = false;
    if ($req($u, '40') !== null && $wait('')
        && $req($u, '42' . json_encode(['REGISTER', ['code' => $key, 'channel' => 'Dashboard', 'name' => 'Media Controller']])) !== null && $wait('SUCCESS')
        && $req($u, '42' . json_encode(['MEDIA_COMMAND', $payload + ['code' => $key]])) !== null) {
        $ok = ($payload['command'] === 'volume') ? true : $wait('MEDIA_QUEUE_UPDATE');
    }
    $req($u, '41');
    return $ok;
}
